// KB Learning Progress Storage
// Tracks review history, confidence, and spaced repetition for KB field cards

const KB_REVIEW_HISTORY_KEY = 'avance_kb_review_history';
const KB_CONFIDENCE_KEY = 'avance_kb_confidence';
const KB_REFLECTIONS_KEY = 'avance_kb_reflections';

export type KbReviewScore = 'Again' | 'Hard' | 'Good' | 'Easy';

export interface KbReviewEntry {
  cardId: string;
  score: KbReviewScore;
  reviewedAt: Date;
}

export interface KbCardProgress {
  cardId: string;
  confidence: number; // 0-100
  reviewCount: number;
  lastReviewDate?: Date;
  nextReviewDate: Date;
}

const canUseLocalStorage = () => typeof window !== 'undefined' && Boolean(window.localStorage);

// Get review history
export const getKbReviewHistory = (): KbReviewEntry[] => {
  if (!canUseLocalStorage()) return [];
  try {
    const raw = window.localStorage.getItem(KB_REVIEW_HISTORY_KEY);
    if (!raw) return [];
    const data = JSON.parse(raw);
    return data.map((entry: any) => ({
      ...entry,
      reviewedAt: new Date(entry.reviewedAt),
    }));
  } catch {
    return [];
  }
};

// Save a review entry
export const saveKbReview = (cardId: string, score: KbReviewScore): void => {
  if (!canUseLocalStorage()) return;
  try {
    const history = getKbReviewHistory();
    history.push({
      cardId,
      score,
      reviewedAt: new Date(),
    });
    window.localStorage.setItem(KB_REVIEW_HISTORY_KEY, JSON.stringify(history));
  } catch {
    // Ignore localStorage errors
  }
};

// Calculate next review date based on score and review count
const calculateNextReviewDate = (score: KbReviewScore, reviewCount: number): Date => {
  const now = new Date();
  let daysUntilNext = 1;

  if (score === 'Easy') {
    // Easy: increase interval based on review count
    daysUntilNext = Math.min(Math.pow(2, reviewCount), 30); // 1, 2, 4, 8, 16, 30...
  } else if (score === 'Good') {
    // Good: moderate interval
    daysUntilNext = Math.max(1, Math.ceil(reviewCount / 2));
  } else if (score === 'Hard') {
    // Hard: come back tomorrow
    daysUntilNext = 1;
  } else if (score === 'Again') {
    // Again: come back same day/next review session
    daysUntilNext = 0;
  }

  const nextReview = new Date(now);
  nextReview.setDate(nextReview.getDate() + daysUntilNext);
  return nextReview;
};

// Get progress for a specific card
export const getKbCardProgress = (cardId: string): KbCardProgress => {
  if (!canUseLocalStorage()) {
    return {
      cardId,
      confidence: 0,
      reviewCount: 0,
      nextReviewDate: new Date(),
    };
  }

  try {
    const history = getKbReviewHistory();
    const reviews = history.filter((e) => e.cardId === cardId);
    const confidenceData = JSON.parse(window.localStorage.getItem(KB_CONFIDENCE_KEY) || '{}');

    const reviewCount = reviews.length;
    const lastReview = reviews[reviews.length - 1];
    const lastScore = lastReview?.score || 'Again';
    const confidence = confidenceData[cardId] ?? 0;

    const nextReviewDate = calculateNextReviewDate(lastScore, reviewCount);

    return {
      cardId,
      confidence,
      reviewCount,
      lastReviewDate: lastReview ? new Date(lastReview.reviewedAt) : undefined,
      nextReviewDate,
    };
  } catch {
    return {
      cardId,
      confidence: 0,
      reviewCount: 0,
      nextReviewDate: new Date(),
    };
  }
};

// Update confidence for a card
export const updateKbConfidence = (cardId: string, confidence: number): void => {
  if (!canUseLocalStorage()) return;
  try {
    const data = JSON.parse(window.localStorage.getItem(KB_CONFIDENCE_KEY) || '{}');
    data[cardId] = Math.min(100, Math.max(0, confidence));
    window.localStorage.setItem(KB_CONFIDENCE_KEY, JSON.stringify(data));
  } catch {
    // Ignore localStorage errors
  }
};

// Save a teach-back reflection
export const saveKbReflection = (cardId: string, reflection: string): void => {
  if (!canUseLocalStorage()) return;
  try {
    const data = JSON.parse(window.localStorage.getItem(KB_REFLECTIONS_KEY) || '{}');
    data[cardId] = reflection;
    window.localStorage.setItem(KB_REFLECTIONS_KEY, JSON.stringify(data));
  } catch {
    // Ignore localStorage errors
  }
};

// Get a teach-back reflection
export const getKbReflection = (cardId: string): string => {
  if (!canUseLocalStorage()) return '';
  try {
    const data = JSON.parse(window.localStorage.getItem(KB_REFLECTIONS_KEY) || '{}');
    return data[cardId] ?? '';
  } catch {
    return '';
  }
};

// Get all card progress (for evidence pack)
export const getAllKbCardProgress = (cardIds: string[]): KbCardProgress[] => {
  return cardIds.map((id) => getKbCardProgress(id));
};

// Get cards due for review today
export const getKbCardsDueForReview = (cardIds: string[]): string[] => {
  const now = new Date();
  return cardIds.filter((id) => {
    const progress = getKbCardProgress(id);
    return progress.nextReviewDate <= now;
  });
};

